// lib/Store/make-cache-manager-store.js
init_Utils();
init_WAProto();
var import_cache_manager = require("cache-manager");
init_logger();
async function makeCacheManagerAuthState(store, sessionKey) {
  const defaultKey = (file) => `${sessionKey}:${file}`;
  const databaseConn = await caching(store);
  const writeData = async (file, data) => {
    let ttl;
    if (file === "creds") {
      ttl = 63115200;
    }
    await databaseConn.set(defaultKey(file), JSON.stringify(data, BufferJSON.replacer), ttl);
  };
  const readData = async (file) => {
    try {
      const data = await databaseConn.get(defaultKey(file));
      if (data) return JSON.parse(data, BufferJSON.reviver);
      return null;
    } catch (error) {
      logger_default.error(error);
      return null;
    }
  };
  const removeData = async (file) => {
    try {
      return await databaseConn.del(defaultKey(file));
    } catch (err) {
      logger_default.error(`Error removing ${file} from session ${sessionKey}`);
    }
  };
  const clearState = async () => {
    try {
      const keys = await databaseConn.store.keys(`${sessionKey}*`);
      await Promise.all(keys.map((key) => databaseConn.del(key)));
    } catch (err) {
    }
  };
  const creds = await readData("creds") || initAuthCreds();
  return {
    clearState,
    saveCreds: () => writeData("creds", creds),
    state: {
      creds,
      keys: {
        get: async (type, ids) => {
          const data = {};
          await Promise.all(
            ids.map(async (id) => {
              let value = await readData(`${type}-${id}`);
              if (type === "app-state-sync-key" && value) {
                value = proto.Message.AppStateSyncKeyData.fromObject(value);
              }
              data[id] = value;
            })
          );
          return data;
        },
        set: async (data) => {
          const tasks = [];
          for (const category in data) {
            for (const id in data[category]) {
              const value = data[category][id];
              const key = `${category}-${id}`;
              tasks.push(value ? writeData(key, value) : removeData(key));
            }
          }
          await Promise.all(tasks);
        }
      }
    }
  };
}

// lib/Store/make-ordered-dictionary.js
function makeOrderedDictionary(idGetter) {
  const array = [];
  const dict = {};
  const get = (id) => dict[id];
  const update = (item) => {
    const id = idGetter(item);
    const idx = array.findIndex((i) => idGetter(i) === id);
    if (idx >= 0) {
      array[idx] = item;
      dict[id] = item;
    }
    return false;
  };
  const upsert = (item, mode) => {
    const id = idGetter(item);
    if (get(id)) {
      update(item);
    } else {
      if (mode === "append") {
        array.push(item);
      } else {
        array.splice(0, 0, item);
      }
      dict[id] = item;
    }
  };
  const remove = (item) => {
    const id = idGetter(item);
    const idx = array.findIndex((i) => idGetter(i) === id);
    if (idx >= 0) {
      array.splice(idx, 1);
      delete dict[id];
      return true;
    }
    return false;
  };
  return {
    array,
    get,
    upsert,
    update,
    remove,
    updateAssign: (id, update2) => {
      const item = get(id);
      if (item) {
        Object.assign(item, update2);
        delete dict[id];
        dict[idGetter(item)] = item;
        return true;
      }
      return false;
    },
    clear: () => {
      array.splice(0, array.length);
      for (const key of Object.keys(dict)) {
        delete dict[key];
      }
    },
    filter: (contain) => {
      let i = 0;
      while (i < array.length) {
        if (!contain(array[i])) {
          delete dict[idGetter(array[i])];
          array.splice(i, 1);
        } else {
          i += 1;
        }
      }
    },
    toJSON: () => array,
    fromJSON: (newItems) => {
      array.splice(0, array.length, ...newItems);
    }
  };
}

